for(let y=0;y<128;y++)for(let x=0;x<64;x++){const edge=Math.min(x,63-x)/16,noise=((x*73856093^y*19349663)>>>0)%101/100;edgeContext.fillStyle=edge>noise?'#fff':'#000';edgeContext.fillRect(x,y,1,1)}
