const rawRoutes={hill:[[0,13],[0,7],[-4,3],[-6,-2],[-5,-7],[0,-11],[0,-14.3]],low:[[0,13],[0,7],[5,4],[8,-1],[7,-7],[3,-11],[0,-14.3]]}
function makeCurve(arr){const flat=new THREE.CatmullRomCurve3(arr.map(([x,z])=>new THREE.Vector3(x,0,z)));const pts=[];for(let i=0;i<=240;i++){const p=flat.getPointAt(i/240);p.y=height(p.x,p.z)+.08;pts.push(p)}return new THREE.CatmullRomCurve3(pts)}
