// A pawn is only a position/scale marker. No character design or gait is authored here.
const pawn=new THREE.Group(),pawnMat=new THREE.MeshStandardMaterial({color:'#302234',roughness:.72}),headMat=new THREE.MeshStandardMaterial({color:'#c4ab7c',roughness:.65})
const body=new THREE.Mesh(new THREE.CylinderGeometry(.24,.46,.92,8),pawnMat);body.position.y=.56;body.castShadow=true;pawn.add(body)
const head=new THREE.Mesh(new THREE.SphereGeometry(.33,10,7),headMat);head.position.y=1.24;head.castShadow=true;pawn.add(head)
